script:
app.beginUndoGroup("Glitch RGB Split");
var comp = app.project.activeItem;
if (!(comp instanceof CompItem)) throw new Error("Open a composition first.");
if (comp.selectedLayers.length < 1) throw new Error("Select at least one layer.");
var selectedLayers = comp.selectedLayers;
var selectedCount = selectedLayers.length;
for (var i = 0; i < selectedCount; i++) {
  var original = selectedLayers[i];
  var baseName = original.name;
  var green = original.duplicate();
  var blue = original.duplicate();
  original.name = baseName + " [R]";
  green.name = baseName + " [G]";
  blue.name = baseName + " [B]";
  blue.moveAfter(original);
  var redEffects = original.property("ADBE Effect Parade");
  var redChannels = redEffects.addProperty("ADBE Shift Channels");
  redChannels.property("ADBE Shift Channels-0001").setValue(1);
  redChannels.property("ADBE Shift Channels-0002").setValue(2);
  redChannels.property("ADBE Shift Channels-0003").setValue(10);
  redChannels.property("ADBE Shift Channels-0004").setValue(10);
  var greenEffects = green.property("ADBE Effect Parade");
  var greenChannels = greenEffects.addProperty("ADBE Shift Channels");
  greenChannels.property("ADBE Shift Channels-0001").setValue(1);
  greenChannels.property("ADBE Shift Channels-0002").setValue(10);
  greenChannels.property("ADBE Shift Channels-0003").setValue(3);
  greenChannels.property("ADBE Shift Channels-0004").setValue(10);
  var blueEffects = blue.property("ADBE Effect Parade");
  var blueChannels = blueEffects.addProperty("ADBE Shift Channels");
  blueChannels.property("ADBE Shift Channels-0001").setValue(1);
  blueChannels.property("ADBE Shift Channels-0002").setValue(10);
  blueChannels.property("ADBE Shift Channels-0003").setValue(10);
  blueChannels.property("ADBE Shift Channels-0004").setValue(4);
  blue.blendingMode = BlendingMode.NORMAL;
  original.blendingMode = BlendingMode.ADD;
  green.blendingMode = BlendingMode.ADD;
  var redTransform = redEffects.addProperty("ADBE Geometry2");
  redTransform.property("ADBE Geometry2-0002").setValue([comp.width / 2 + 8, comp.height / 2]);
  var greenTransform = greenEffects.addProperty("ADBE Geometry2");
  greenTransform.property("ADBE Geometry2-0002").setValue([comp.width / 2 - 8, comp.height / 2]);
}
app.endUndoGroup();
